custom_css:
/* ===== src/tokens.css ===== */

/*
 * Theme: 草莓果酱
 * Author: @jiuyi0204
 * 未经作者明确许可，禁止二次修改、二次上传、转载、重新打包或冒名发布。
 */
@font-face {
    font-family: "Huiwen-mincho";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/huiwenmincho-improved/HuiwenMincho-Improved-Regular.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

@font-face {
    font-family: "Cormorant SC";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/cormorant-sc/CormorantSC-Regular.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    --jam-chocolate: #2b1818;
    --jam-chocolate-soft: #432526;
    --jam-red: #c9363d;
    --jam-red-deep: #9f242d;
    --jam-cream: #f4eadb;
    --jam-paper: #fff9ef;
    --jam-paper-warm: #ead7bf;
    --jam-green: #697d46;
    --jam-green-dark: #46592c;
    --jam-ink: #2b1d1a;
    --jam-muted: #806d62;
    --jam-info: #697d46;
    --jam-success: #486e43;
    --jam-warning: #a66a30;
    --jam-error: #ad2835;
    --jam-border: rgba(201, 54, 61, 0.54);
    --jam-hairline: 1px solid var(--jam-red);
    --jam-shadow: 0 1.1rem 2.8rem rgba(43, 24, 24, 0.22);
    --jam-font-body: "Huiwen-mincho", "Noto Serif SC", "Songti SC", serif;
    --jam-font-display: "Cormorant SC", "Huiwen-mincho", Georgia, serif;
    --jam-radius-paper: 0.15rem;
    --jam-gap-xs: 0.35rem;
    --jam-gap-sm: 0.65rem;
    --jam-gap-md: 1rem;
    --jam-gap-lg: 1.6rem;
    --jam-avatar-size: 2.7rem;
    --jam-avatar-gap: 0.65rem;
    --jam-avatar-slot: 0rem;
    --jam-user-portrait-width: clamp(12rem, 26vw, 22rem);
    --jam-user-portrait-min-height: clamp(16rem, 32vw, 27rem);
}

body {
    --SmartThemeBodyColor: var(--jam-ink);
    --SmartThemeEmColor: var(--jam-red-deep);
    --SmartThemeUnderlineColor: var(--jam-red);
    --SmartThemeQuoteColor: var(--jam-green-dark);
    --SmartThemeBlurTintColor: rgba(244, 234, 219, 0.96);
    --SmartThemeChatTintColor: rgba(244, 234, 219, 0.97);
    --SmartThemeUserMesBlurTintColor: rgba(255, 249, 239, 0.98);
    --SmartThemeBotMesBlurTintColor: rgba(255, 249, 239, 0.98);
    --SmartThemeShadowColor: rgba(43, 24, 24, 0.22);
    --SmartThemeBorderColor: var(--jam-red);
    background: var(--jam-chocolate);
    color: var(--jam-ink);
    font-family: var(--jam-font-body);
}


/* ===== src/kernel/state-protection.css ===== */

/* 功能/状态保护：不放主题构图。 */
#chat :is(button, [role="button"], .menu_button, .mes_button):focus-visible,
#top-bar :is(button, [role="button"], .drawer-toggle):focus-visible,
#send_form :is(button, textarea, [role="button"], .menu_button):focus-visible,
.drawer-content :is(button, input, textarea, select, [role="button"]):focus-visible,
.popup :is(button, input, textarea, select, [role="button"]):focus-visible {
    outline: 2px solid var(--jam-green);
    outline-offset: 3px;
}

#chat::before,
#chat .mes::before,
#chat .mes_block::before,
#top-bar::before,
#send_form::before {
    pointer-events: none;
}

:is(button, input, textarea, select, .menu_button)[disabled],
:is(button, input, textarea, select, .menu_button).disabled {
    color: var(--jam-muted);
    opacity: 0.62;
    filter: none;
}

@media (prefers-reduced-motion: reduce) {
    #chat,
    #chat .mes,
    #chat .mes_block,
    #chat .mes_buttons,
    #top-bar,
    #top-bar .drawer-toggle,
    #send_form,
    #send_form .menu_button,
    .drawer-content,
    .drawer-content .menu_button,
    .popup,
    .popup .menu_button {
        scroll-behavior: auto;
        transition-duration: 0.01ms;
        animation-duration: 0.01ms;
        animation-iteration-count: 1;
    }
}


/* ===== src/chat-layout.css ===== */

/* W01: L12 横向杂志拼贴。User 真实头像是左侧封面，Character 头像是消息头邮票章。 */
#chat {
    position: relative;
    isolation: isolate;
    box-sizing: border-box;
    padding: 7rem clamp(1rem, 5vw, 5rem) 8rem;
    background-color: var(--jam-cream);
    background-image:
        linear-gradient(100deg, transparent 0 82%, var(--jam-green) 82% 100%),
        linear-gradient(168deg, var(--jam-red) 0 10.5rem, transparent 10.55rem),
        linear-gradient(90deg, var(--jam-chocolate) 0 22%, transparent 22.1% 100%);
    background-repeat: no-repeat;
    background-position: center;
    background-size: 100% 100%;
    color: var(--jam-ink);
    border: 0;
}

#chat::before {
    content: "STRAWBERRY JAM  /  MAIN CHAT";
    display: block;
    margin: 0 0 2.2rem;
    padding: 0.8rem 0 0.65rem;
    color: var(--jam-red);
    border-bottom: 2px solid var(--jam-red);
    font-family: var(--jam-font-display);
    font-size: clamp(1.25rem, 2vw, 2rem);
    letter-spacing: 0.13em;
    text-transform: uppercase;
}

#chat .mes {
    position: relative;
    display: flex;
    width: 100%;
    max-width: 76rem;
    min-width: 0;
    margin: 0 auto 1.2rem;
    padding: 0;
    border: 0;
    background: transparent;
    box-shadow: none;
    color: var(--jam-ink);
}

#chat .mes[is_user="false"][is_system="false"] .mesAvatarWrapper {
    position: absolute;
    z-index: 2;
    top: 1.05rem;
    left: 1rem;
    width: var(--jam-avatar-size);
    min-width: var(--jam-avatar-size);
    margin: 0;
    pointer-events: auto;
}

#chat .mes[is_user="false"][is_system="false"] .mesAvatarWrapper .avatar {
    width: var(--jam-avatar-size);
    height: var(--jam-avatar-size);
    margin: 0;
    padding: 0.18rem;
    border: 2px solid var(--jam-red);
    border-radius: 0;
    background: var(--jam-paper);
    box-shadow: 0.22rem 0.24rem 0 var(--jam-chocolate-soft);
    transform: rotate(-2deg);
}

#chat .mes[is_user="false"][is_system="false"] .mesAvatarWrapper .avatar img {
    width: 100%;
    height: 100%;
    border-radius: 0;
    object-fit: cover;
}

#chat .mes_block {
    box-sizing: border-box;
    flex: 1 1 auto;
    min-width: 0;
    width: 100%;
    margin: 0;
    color: var(--jam-ink);
}

#chat .mes[is_user="false"][is_system="false"] .mes_block {
    padding: 1.2rem clamp(1rem, 2.3vw, 2.5rem) 1.7rem;
    border: var(--jam-hairline);
    border-radius: var(--jam-radius-paper);
    background: rgba(255, 249, 239, 0.965);
    box-shadow: var(--jam-shadow);
}

#chat .mes[is_user="false"][is_system="false"] .ch_name {
    min-height: calc(var(--jam-avatar-size) + 0.25rem);
    padding: 0.15rem 0 0.75rem calc(var(--jam-avatar-size) + var(--jam-avatar-gap));
    border-bottom: var(--jam-hairline);
}

#chat .mes[is_user="true"] {
    align-items: stretch;
    gap: clamp(1rem, 3vw, 2.5rem);
    max-width: 76rem;
    margin-inline: auto;
    padding: clamp(0.75rem, 1.5vw, 1.2rem);
    background: linear-gradient(106deg, rgba(43, 24, 24, 0.98) 0 35%, rgba(244, 234, 219, 0.1) 35.1% 100%);
}

#chat .mes[is_user="true"] .mesAvatarWrapper {
    position: relative;
    z-index: 1;
    top: auto;
    right: auto;
    left: auto;
    flex: 0 0 var(--jam-user-portrait-width);
    width: var(--jam-user-portrait-width);
    min-width: var(--jam-user-portrait-width);
    margin: 0;
    align-self: stretch;
    display: flex;
    flex-direction: column;
    pointer-events: auto;
}

#chat .mes[is_user="true"] .mesAvatarWrapper .avatar {
    width: 100%;
    height: 100%;
    max-width: none;
    max-height: none;
    min-height: var(--jam-user-portrait-min-height);
    margin: 0;
    padding: 0;
    border-color: var(--jam-green);
    border-width: 0 0 0.45rem;
    border-style: solid;
    border-radius: 0;
    background: var(--jam-chocolate-soft);
    box-shadow: 0.55rem 0.65rem 0 var(--jam-red);
    transform: rotate(-1deg);
    overflow: hidden;
}

#chat .mes[is_user="true"] .mesAvatarWrapper .avatar img {
    display: block;
    width: 100%;
    height: 100%;
    max-width: none;
    max-height: none;
    min-height: var(--jam-user-portrait-min-height);
    border-radius: 0;
    object-fit: cover;
    object-position: center 20%;
    filter: saturate(0.78) contrast(1.08) sepia(0.12);
}

#chat .mes[is_user="true"] .mesAvatarWrapper::after {
    content: "USER  /  PORTRAIT";
    position: absolute;
    right: 0.65rem;
    bottom: 0.75rem;
    padding: 0.25rem 0.4rem;
    background: var(--jam-red);
    color: var(--jam-cream);
    font-family: var(--jam-font-display);
    font-size: 0.72em;
    letter-spacing: 0.12em;
    pointer-events: none;
}

#chat .mes[is_user="true"] .mes_block {
    align-self: center;
    padding: clamp(1rem, 2.4vw, 2.2rem);
    border: 0;
    border-bottom: 2px solid var(--jam-red);
    background: rgba(255, 249, 239, 0.94);
    box-shadow: none;
}

#chat .mes[is_user="true"] .ch_name {
    justify-content: flex-end;
    min-height: 1.45rem;
    color: var(--jam-red-deep);
}

#chat .mes[is_system="true"] .mes_block,
#chat .smallSysMes {
    padding: 0.7rem 1rem;
    border-left: 0.35rem solid var(--jam-green);
    background: rgba(234, 215, 191, 0.92);
    color: var(--jam-chocolate-soft);
}

#chat .name_text,
#chat .timestamp,
#chat .mesIDDisplay,
#chat .tokenCounterDisplay,
#chat .mes_timer {
    color: inherit;
    font-family: var(--jam-font-display);
    letter-spacing: 0.055em;
    text-shadow: none;
}

#chat .name_text {
    color: var(--jam-red-deep);
    font-size: 1.08em;
}

#chat .timestamp,
#chat .mesIDDisplay,
#chat .tokenCounterDisplay,
#chat .mes_timer {
    color: var(--jam-muted);
    font-size: 0.78em;
    opacity: 1;
}

#chat .mes_buttons {
    color: var(--jam-red);
    filter: none;
}

#chat .mes_buttons :is(.mes_button, .fa-solid, .fa-regular) {
    color: var(--jam-red);
    opacity: 0.82;
    filter: none;
    transition: color 120ms ease, transform 120ms ease, opacity 120ms ease;
}

#chat .mes_buttons :is(.mes_button, .fa-solid, .fa-regular):hover,
#chat .mes_buttons :is(.mes_button, .fa-solid, .fa-regular):focus-visible {
    color: var(--jam-green-dark);
    opacity: 1;
    transform: translateY(-1px);
}

#chat .mes_reasoning_details {
    margin: 0.8rem 0;
    border: 1px dashed var(--jam-green);
    background: rgba(105, 125, 70, 0.1);
    color: var(--jam-ink);
}

#chat :is(.mes_media_wrapper, .mes_file_wrapper) {
    max-width: 100%;
    border: var(--jam-hairline);
    background: var(--jam-paper);
}

#chat :is(.swipe_left, .swipeRightBlock, .swipes-counter) {
    color: var(--jam-red-deep);
    filter: none;
}


/* ===== src/full-text.css ===== */

/* T02 杂志编辑：只处理正文语义，不修正父级头像空间。 */
#chat .mes_text {
    max-width: 72ch;
    margin-inline: auto;
    color: var(--jam-ink);
    font-family: var(--jam-font-body);
    font-size: 0.98em;
    font-weight: 400;
    line-height: 1.9;
    letter-spacing: 0.018em;
    overflow-wrap: anywhere;
}

#chat .mes[is_user="true"] .mes_text {
    max-width: 100%;
    margin: 0.25rem 0 0;
    font-size: 1.06em;
    line-height: 1.65;
    text-align: right;
}

#chat .mes_text p {
    margin: 0 0 1.15em;
}

#chat .mes_text p:last-child {
    margin-bottom: 0;
}

#chat .mes_text :is(h1, h2, h3, h4, h5, h6) {
    margin: 1.35em 0 0.6em;
    color: var(--jam-red-deep);
    font-family: var(--jam-font-display);
    font-weight: 400;
    line-height: 1.2;
    letter-spacing: 0.08em;
}

#chat .mes_text :is(strong, b) {
    color: var(--jam-red-deep);
    font-weight: 400;
    letter-spacing: 0.06em;
}

#chat .mes_text em {
    color: var(--jam-green-dark);
}

#chat .mes_text blockquote {
    margin: 1.15em 0;
    padding: 0.6em 1.1em;
    border: 0;
    border-left: 0.35em solid var(--jam-green);
    background: rgba(105, 125, 70, 0.09);
    color: var(--jam-chocolate-soft);
}

#chat .mes_text :is(ul, ol) {
    margin: 0.8em 0 1.1em;
    padding-inline-start: 1.6em;
}

#chat .mes_text li::marker {
    color: var(--jam-red);
}

#chat .mes_text :is(code, kbd) {
    border: 1px solid rgba(159, 36, 45, 0.26);
    border-radius: 0;
    background: var(--jam-paper-warm);
    color: var(--jam-red-deep);
    font-family: "Courier Prime", Consolas, monospace;
}

#chat .mes_text pre {
    max-width: 100%;
    padding: 1em;
    overflow-x: auto;
    border-left: 0.35em solid var(--jam-red);
    background: var(--jam-chocolate);
    color: var(--jam-cream);
}

#chat .mes_text pre code {
    border: 0;
    background: transparent;
    color: inherit;
}

#chat .mes_text table {
    display: block;
    max-width: 100%;
    overflow-x: auto;
    border-collapse: collapse;
}

#chat .mes_text :is(th, td) {
    padding: 0.55em 0.75em;
    border: 1px solid var(--jam-border);
}

#chat .mes_text th {
    background: var(--jam-red);
    color: var(--jam-cream);
    font-family: var(--jam-font-display);
    font-weight: 400;
    letter-spacing: 0.06em;
}

#chat .mes_text hr {
    margin: 1.6em auto;
    border: 0;
    border-top: 2px solid var(--jam-red);
}

#chat .mes_text a {
    color: var(--jam-red-deep);
    text-decoration-color: var(--jam-green);
    text-underline-offset: 0.18em;
}

#chat .mes_text :is(img, video, audio) {
    max-width: 100%;
    height: auto;
}

#chat .mes_text details {
    margin: 1em 0;
    padding: 0.7em 0.9em;
    border: 1px dashed var(--jam-green);
    background: rgba(255, 249, 239, 0.7);
}


/* ===== src/windows/topbar.css ===== */

/* W02 顶栏：无重复方框的印刷工具列，保留原图标作为可靠回退。 */
#top-bar {
    min-height: 3.6rem;
    padding: 0.35rem clamp(0.5rem, 2vw, 1.5rem);
    border: 0;
    border-bottom: 2px solid var(--jam-cream);
    background: var(--jam-red);
    box-shadow: 0 0.55rem 1.4rem rgba(43, 24, 24, 0.22);
    color: var(--jam-cream);
}

#top-bar :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) {
    min-width: 2.55rem;
    min-height: 2.55rem;
    margin: 0 0.16rem;
    border: 0;
    border-radius: 0;
    background: transparent;
    color: var(--jam-cream);
    opacity: 0.9;
    filter: none;
    text-shadow: none;
    transition: transform 120ms ease, color 120ms ease, opacity 120ms ease;
}

#top-bar :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder):hover,
#top-bar :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder):focus-visible,
#top-bar :is(.drawer-toggle.open, .drawer-toggle.active) {
    color: var(--jam-chocolate);
    opacity: 1;
    transform: translateY(-0.12rem) rotate(-2deg);
}

#top-bar .drawer-toggle::after {
    content: "";
    display: block;
    width: 0;
    height: 2px;
    margin: 0.2rem auto 0;
    background: currentColor;
    transition: width 120ms ease;
}

#top-bar .drawer-toggle:hover::after,
#top-bar .drawer-toggle:focus-visible::after,
#top-bar .drawer-toggle.open::after {
    width: 70%;
}


/* ===== src/windows/input.css ===== */

/* W03 输入工作台 */
#send_form {
    box-sizing: border-box;
    min-height: 4.4rem;
    padding: 0.42rem 0.55rem;
    border: 2px solid var(--jam-red);
    border-radius: 0;
    background: rgba(255, 249, 239, 0.985);
    box-shadow: 0 -0.75rem 2rem rgba(43, 24, 24, 0.16);
    color: var(--jam-ink);
}

#send_textarea {
    min-height: 3rem;
    border: 0;
    border-radius: 0;
    background: transparent;
    color: var(--jam-ink);
    font-family: var(--jam-font-body);
    font-size: 0.98em;
    line-height: 1.55;
    box-shadow: none;
}

#send_textarea::placeholder {
    color: var(--jam-muted);
    opacity: 0.82;
}

#leftSendForm,
#rightSendForm {
    align-items: center;
    gap: 0.2rem;
}

#leftSendForm .menu_button,
#rightSendForm .menu_button,
#send_but,
#send_form .fa-solid,
#send_form .fa-regular {
    min-width: 2.65rem;
    min-height: 2.65rem;
    border: 0;
    border-radius: 0;
    background: transparent;
    color: var(--jam-red);
    opacity: 0.94;
    filter: none;
    text-shadow: none;
}

#send_but {
    border-left: 1px solid var(--jam-border);
    font-size: 1.25em;
}

#leftSendForm .menu_button:hover,
#rightSendForm .menu_button:hover,
#send_but:hover,
#leftSendForm .menu_button:focus-visible,
#rightSendForm .menu_button:focus-visible,
#send_but:focus-visible {
    color: var(--jam-green-dark);
    transform: translateY(-1px) rotate(-2deg);
}

#send_form .stop_button,
#send_form [data-state="stop"] {
    color: var(--jam-error);
}


/* ===== src/windows/textgen.css ===== */

/* W04 文本补全参数 */
#left-nav-panel,
#textgenerationwebui_api-settings,
#textgenerationwebui_api-presets {
    background: rgba(244, 234, 219, 0.985);
    color: var(--jam-ink);
    font-family: var(--jam-font-body);
}

#left-nav-panel {
    border-right: 3px solid var(--jam-red);
    box-shadow: 0.8rem 0 2.2rem rgba(43, 24, 24, 0.2);
}

#left-nav-panel :is(h3, h4, .inline-drawer-header) {
    color: var(--jam-red-deep);
    font-family: var(--jam-font-display);
    font-weight: 400;
    letter-spacing: 0.055em;
}

#left-nav-panel :is(input, textarea, select),
#textgenerationwebui_api-settings :is(input, textarea, select),
#textgenerationwebui_api-presets {
    border: 1px solid var(--jam-border);
    border-radius: 0;
    background: var(--jam-paper);
    color: var(--jam-ink);
    box-shadow: none;
}

#left-nav-panel :is(option, optgroup),
#textgenerationwebui_api-settings :is(option, optgroup) {
    background: var(--jam-paper);
    color: var(--jam-ink);
}

#left-nav-panel input[type="range"],
#textgenerationwebui_api-settings input[type="range"] {
    accent-color: var(--jam-red);
}

#left-nav-panel input[type="range"]::-webkit-slider-thumb,
#textgenerationwebui_api-settings input[type="range"]::-webkit-slider-thumb {
    border: 2px solid var(--jam-cream);
    background: var(--jam-red);
    box-shadow: 0 0 0 1px var(--jam-red-deep);
}

#left-nav-panel :is(input[type="checkbox"], input[type="radio"]),
#textgenerationwebui_api-settings :is(input[type="checkbox"], input[type="radio"]) {
    accent-color: var(--jam-green-dark);
}


/* ===== src/windows/api.css ===== */

/* W05 API 连接 */
#rm_api_block {
    background: rgba(244, 234, 219, 0.985);
    color: var(--jam-ink);
    border-left: 0.35rem solid var(--jam-green);
}

#rm_api_block :is(h3, h4, h5) {
    color: var(--jam-red-deep);
    font-family: var(--jam-font-display);
    font-weight: 400;
    letter-spacing: 0.055em;
}

#rm_api_block :is(input, textarea, select) {
    border: 1px solid var(--jam-border);
    border-radius: 0;
    background: var(--jam-paper);
    color: var(--jam-ink);
    box-shadow: none;
}

#rm_api_block :is(option, optgroup) {
    background: var(--jam-paper);
    color: var(--jam-ink);
}

#rm_api_block :is(.menu_button, button) {
    border: 1px solid var(--jam-red);
    border-radius: 0;
    background: transparent;
    color: var(--jam-red-deep);
    box-shadow: none;
}

#rm_api_block :is(.menu_button, button):hover,
#rm_api_block :is(.menu_button, button):focus-visible {
    background: var(--jam-red);
    color: var(--jam-cream);
}

#rm_api_block :is(.success, .connected) { color: var(--jam-success); }
