.toast-error { color: var(--jam-error); }

#toast-container .toast-message,
#toast-container .toast-title,
#toast-container .toast-close-button {
    color: inherit;
    text-shadow: none;
}

.tooltip,
.ui-tooltip {
    border: 1px solid var(--jam-red);
    border-radius: 0;
