}


/* ===== src/windows/mobile.css ===== */

/* W14 手机端：单列刊物，不改应用级抽屉开关与宽度。 */
@media (max-width: 700px) {
    :root {
        --jam-avatar-size: 2.25rem;
        --jam-avatar-gap: 0.45rem;
        --jam-user-portrait-width: 100%;
        --jam-user-portrait-min-height: clamp(11rem, 54vw, 17rem);
    }

    #top-bar {
        min-height: 3.25rem;
        padding-inline: 0.25rem;
        overflow-x: auto;
        overscroll-behavior-inline: contain;
    }

    #top-bar :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) {
        min-width: 2.7rem;
        min-height: 2.7rem;
        margin-inline: 0.04rem;
    }

    #chat {
        padding: 5.1rem 0.7rem 7.1rem;
        background-image:
            linear-gradient(180deg, rgba(43, 24, 24, 0.08) 0 8.5rem, transparent 8.55rem),
            linear-gradient(180deg, var(--jam-red) 0 4.25rem, transparent 4.3rem),
            linear-gradient(90deg, var(--jam-cream), var(--jam-cream));
        background-repeat: no-repeat;
        background-position: center;
        background-size: 100% 100%;
    }

    #chat::before {
        margin-bottom: 1rem;
        padding: 0.55rem 0;
        font-size: 1.05rem;
        letter-spacing: 0.08em;
    }

    #chat .mes {
        max-width: 100%;
        margin-bottom: 0.8rem;
    }

    #chat .mes[is_user="true"] {
        flex-direction: column;
        gap: 0.8rem;
        max-width: 100%;
        padding: 0.55rem;
        background: var(--jam-chocolate);
    }

    #chat .mes[is_user="true"] .mesAvatarWrapper {
        flex-basis: auto;
        width: 100%;
        min-width: 0;
    }

    #chat .mes[is_user="true"] .mesAvatarWrapper .avatar,
    #chat .mes[is_user="true"] .mesAvatarWrapper .avatar img {
        min-height: var(--jam-user-portrait-min-height);
        height: var(--jam-user-portrait-min-height);
    }

    #chat .mes[is_user="true"] .mesAvatarWrapper .avatar {
        transform: none;
        box-shadow: 0.35rem 0.4rem 0 var(--jam-red);
    }

    #chat .mes[is_user="false"][is_system="false"] .mes_block {
        padding: 0.85rem 0.8rem 1.15rem;
    }

    #chat .mes[is_user="false"][is_system="false"] .ch_name {
        padding-left: calc(var(--jam-avatar-size) + var(--jam-avatar-gap));
    }

    #chat .mes[is_user="true"] .mes_block {
        width: 100%;
        padding: 0.85rem 0.75rem;
    }

    #chat .mes_text {
        max-width: 100%;
        font-size: 0.98em;
        line-height: 1.75;
    }

    #send_form {
        min-height: 3.75rem;
        padding: 0.25rem 0.3rem max(0.25rem, env(safe-area-inset-bottom));
    }

    #leftSendForm .menu_button,
    #rightSendForm .menu_button,
    #send_but {
        min-width: 2.75rem;
        min-height: 2.75rem;
    }

    #left-nav-panel,
    #right-nav-panel,
    #user-settings-block,
    #rm_api_block,
    #AdvancedFormatting,
    #WorldInfo,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement {
        background-color: rgba(244, 234, 219, 0.995);
        box-shadow: none;
    }
}


